def check_solution(edges, n=14):
    degrees = [0] * n
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1

    print("Degrees:", degrees)
    for d in degrees:
        if d < 4 or d > 5:
            return False
    return True

fixed_edges = [(1, 11), (0, 13), (7, 9), (1, 13), (4, 11), (6, 9)]
edges = [(0, 1), (0, 2), (0, 6), (0, 7), (0, 13), (1, 2), (1, 7), (1, 11), (1, 13), (2, 4), (2, 5), (2, 6), (3, 4), (3, 5), (3, 7), (3, 8), (4, 5), (4, 8), (4, 11), (5, 6), (6, 9), (7, 9), (8, 10), (8, 12), (9, 10), (9, 12), (10, 11), (10, 12), (10, 13), (11, 12), (11, 13)]

# Check if all fixed edges are present
for fe in fixed_edges:
    if fe not in edges and (fe[1], fe[0]) not in edges:
        print(f"Missing fixed edge: {fe}")

print(check_solution(edges))
